var TEX = null;
/** The table as a 3D texture, made once: both lattices read the same one (uniform uCells). */
function cellTexture() {
	if (!TEX) {
		TEX = new Data3DTexture(CELLS.data, ...CELLS.size);
		TEX.needsUpdate = true;
	}
	return TEX;
}
/** GLSL: cell(id), a cell's four numbers (0 … 1): from the table where it has the cell, from a hash elsewhere. */
var CELLS_GLSL = `
uniform highp sampler3D uCells;
vec4 cell(vec3 id) {
  ivec3 c = ivec3(id) - ivec3(${CELLS.lo.join(", ")});
  if (all(greaterThanEqual(c, ivec3(0))) && all(lessThan(c, ivec3(${CELLS.size.join(", ")})))) return texelFetch(uCells, c, 0);
  return vec4(hash33(id + vec3(0., 0., 1000.)), hash33(id + vec3(0., 0., 2000.)).x);
}`;
//#endregion
export { CELLS, CELLS_GLSL, cellTexture };
